<script lang="ts">
 import companions from '#lib/locales/de/story-companions.json';import storyMedia from '#lib/story-media.json';
 import {atlasArticles,enrichAtlasArticle} from '#lib/atlas-content.ts';import {catalog} from '#lib/catalog.svelte.ts';
 import ArticleBody from '#lib/components/learning/ArticleBody.svelte';
 import {t} from '#lib/i18n.ts';
 import {imageCredits}from'#lib/content.ts';import{getArticles,getWines,getArticle as articleBySlug,imageSrc,creditFor}from'#lib/editorial.svelte.ts';const articles=$derived(getArticles(atlasArticles).map(enrichAtlasArticle));const credits=$derived([...Object.values(companions).map(story=>({text:story.credit,url:storyMedia[story.photo as keyof typeof storyMedia].source})),...new Map(articles.filter(a=>a.image).map(a=>{const c=creditFor(a);return[c.text,c] as const;})).values(),...getWines().filter(w=>w.bottleImage).map(w=>({text:w.producer+' · '+w.name+' · '+w.bottleCredit,url:w.bottleSource}))]);function licenseFor(text:string){const match=text.match(/CC BY(-SA)? ([0-9.]+)/);return match?'https://creativecommons.org/licenses/by'+(match[1]?'-sa':'')+'/'+match[2]+'/':text.includes('CC0')?'https://creativecommons.org/publicdomain/zero/1.0/':'';}import Icon from '#lib/components/Icon.svelte';let {data}=$props();const article=$derived(data.article?articleBySlug(data.article.slug,atlasArticles):null);
</script>
<svelte:head><title>{article?.title||'Bildnachweise'} {t('m_46c3600dd1')}</title></svelte:head>
<div class="page-content reading-page"><a class="back-link" href={'/entdecken'+(catalog.lastOpenSlug?'#artikel-'+catalog.lastOpenSlug:'')}><Icon name="left" size={16}/>{t('m_9eed371f21')}</a>
{#if article}<header class="reading-header"><div class="reading-meta"><span class="pill">{article.category}</span><span>{Math.max(1,Math.ceil([article.intro,...article.paragraphs,...(article.sections||[]).map(s=>s.body)].join(' ').split(/\s+/).length/180))} Min. Lesezeit</span></div><h1>{article.title}{#if !/[.!?…]$/.test(article.title.trim())}<span class="accent">.</span>{/if}</h1><p class="lead">{article.intro}</p></header>{#if article.image}<figure class="article-image" style="margin-left:0;margin-right:0"><img class='editorial-image' style={'--image-position:'+(article.imagePosition||'center')+';--image-position-mobile:'+(article.imagePositionMobile||article.imagePosition||'center')+';--image-fit:'+(article.imageFit||'cover')} src={imageSrc(article.image)} alt={article.imageAlt||(article.image==='saar-illustration'?'Illustration eines Schiefer-Flusstals':article.category==='Regionen'?'Weinlandschaft: '+article.title:'Illustration zum Thema '+article.title)}/><figcaption class="image-credit">{creditFor(article).text}</figcaption></figure>{/if}<ArticleBody {article}/><div class="fact-box"><Icon name="sparkles" size={21}/><div><small>{t('m_9b729ef16b')}</small>{article.fact}</div></div>{#if article.related?.length}<div class="section-heading" style="margin-top:32px"><h2>{t('m_c4598f132c')}</h2></div><div class="related-links">{#each article.related as slug}{@const related=articleBySlug(slug,atlasArticles)}{#if related}<a href={'/entdecken/'+slug}>{related.title}<Icon name="right" size={15}/></a>{/if}{/each}</div>{/if}
{:else}<header class="reading-header"><h1>Bildnachweise<span class="accent">.</span></h1></header><div class="info-list">{#each credits as credit}<div><p>{credit.text}</p>{#if credit.url}<a href={credit.url} target="_blank" rel="noreferrer">Originalbild & Nutzungsangaben ↗</a>{/if}{#if licenseFor(credit.text)}<p><a href={licenseFor(credit.text)} target='_blank' rel='noreferrer'>Bildlizenz ↗</a> · Darstellung teilweise als Ausschnitt.</p>{/if}</div>{/each}<div><p>Erklärgrafiken: eigene schematische SVG-Darstellungen.</p><p>Kartengrundlage: Natural Earth (Public Domain). Ortskoordinaten: © OpenStreetMap-Mitwirkende.</p><a href='https://www.openstreetmap.org/copyright' target='_blank' rel='noreferrer'>OpenStreetMap · Nutzungsangaben ↗</a></div></div>{/if}</div>
